    let args = Args::parse();
    let pool = MySqlPoolOptions::new()
        .max_connections(5)
        .connect(&args.database_url)
        .await?;

    let start_time = Instant::now();

    create_large_table(&pool).await?;

    let duration = start_time.elapsed();
    println!("Finished creating the table in {:?}.", duration);

    Ok(())
}
```
